@keyframes search-fade-in { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}









































@property --announcement-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }



@keyframes announcement-modal-spin { 
  100% { --announcement-angle: 360deg; }
}









































@keyframes ln-pro-flow { 
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes ln-pro-shine { 
  0% { background-position: -200% 0px; }
  100% { background-position: 200% 0px; }
}













@keyframes ln-menu-fade-in { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}






@keyframes ln-menu-slide-in { 
  0% { opacity: 0; transform: translateY(-6px); }
  100% { opacity: 1; transform: translateY(0px); }
}





































































































































@keyframes marqueeScroll { 
  0% { transform: translate(0px); }
  100% { transform: translate(-50%); }
}
@keyframes marqueeScrollRev { 
  0% { transform: translate(-50%); }
  100% { transform: translate(0px); }
}





























@keyframes spinCW { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes spinCCW { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(-360deg); }
}




















@keyframes thinkPulse { 
  0%,100% { opacity: 0.2; transform: scale(0.85); }
  50% { opacity: 0.7; transform: scale(1); }
}










@keyframes cursorBlink { 
  0%,100% { opacity: 1; }
  50% { opacity: 0; }
}

















@keyframes testScrollUp { 
  0% { transform: translateY(0px); }
  100% { transform: translateY(-33.333%); }
}
@keyframes testScrollDown { 
  0% { transform: translateY(-33.333%); }
  100% { transform: translateY(0px); }
}




































































































































































@property --cta-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }





@keyframes cta-border-spin { 
  100% { --cta-angle: 360deg; }
}







































@keyframes ln-loader-pulse { 
  0%,100% { opacity: 0.3; transform: scale(1); }
  50% { opacity: 0.7; transform: scale(1.08); }
}






@keyframes ln-fade-in { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}


@keyframes skeleton-shimmer { 
  0% { background-position: 200% 0px; }
  100% { background-position: -200% 0px; }
}




























































































@property --border-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes rotateBorder { 
  100% { --border-angle: 360deg; }
}































